from dataclasses import dataclass
from typing import Iterator, Dict, Any

@dataclass
class RecognitionRequest:
    audio_chunks: Iterator[bytes]
    sample_rate_hz: int
    language_code: str
    enable_automatic_punctuation: bool = False

@dataclass
class SpeechRecognitionResult:
    text: str
    is_final: bool
    language_code: str = "en-US"

def normalize_response(response: Dict[str, Any]) -> SpeechRecognitionResult:
    # This is a placeholder for potential response normalization
    # In a real scenario, this would parse the provider's response format
    # For Google Cloud Speech-to-Text, the stream_microphone already handles basic parsing.
    # This function could be expanded to handle more complex scenarios or different providers.
    return SpeechRecognitionResult(
        text=response.get("text", ""),
        is_final=response.get("is_final", False),
        language_code=response.get("language_code", "en-US")
    )

from google.cloud import speech
from speech_models import RecognitionRequest
from typing import Iterator, Dict, Any

class SpeechClient:
    def __init__(self):
        self._client = speech.SpeechClient()

    def streaming_recognize(self, request: RecognitionRequest, config: Dict[str, Any] = None) -> Iterator[Dict[str, Any]]:
        recognition_config = speech.RecognitionConfig(
            encoding=speech.RecognitionConfig.AudioEncoding.LINEAR16,
            sample_rate_hertz=request.sample_rate_hz,
            language_code=request.language_code,
            enable_automatic_punctuation=request.enable_automatic_punctuation
        )
        streaming_config = speech.StreamingRecognitionConfig(
            config=recognition_config,
            interim_results=True
        )

        def generate_requests():
            for chunk in request.audio_chunks:
                yield speech.StreamingRecognizeRequest(audio_content=chunk)

        responses = self._client.streaming_recognize(
            config=streaming_config,
            requests=generate_requests()
        )

        for response in responses:
            for result in response.results:
                if result.alternatives:
                    yield {
                        "text": result.alternatives[0].transcript,
                        "is_final": result.is_final,
                        "language_code": result.language_code # This might not be directly available in all results, depends on API
                    }

from google.cloud import translate_v2 as translate
from speech_models import SpeechRecognitionResult
from typing import Iterator

class Translator:
    def __init__(self, target_language: str):
        self._client = translate.Client()
        self.target_language = target_language

    def translate_caption(self, caption: SpeechRecognitionResult) -> SpeechRecognitionResult:
        if not caption.text:
            return caption

        # Google Cloud Translation API
        # The source language is automatically detected by the API if not specified.
        translation = self._client.translate(
            caption.text, target_language=self.target_language)

        return SpeechRecognitionResult(
            text=translation["translatedText"],
            is_final=caption.is_final,
            language_code=self.target_language # Update to the target language
        )

def live_caption_translate(captions: Iterator[SpeechRecognitionResult], target_language: str) -> Iterator[SpeechRecognitionResult]:
    translator = Translator(target_language)
    for caption in captions:
        yield translator.translate_caption(caption)

from google.cloud import language_v2
from speech_models import SpeechRecognitionResult
from typing import Iterator, Dict, Any

class SafetyChecker:
    def __init__(self):
        self._client = language_v2.LanguageServiceClient()

    def check_safety(self, caption: SpeechRecognitionResult) -> Dict[str, Any]:
        if not caption.text:
            return {"text": caption.text, "is_safe": True, "categories": []}

        # Google Cloud Natural Language API for content moderation
        document = language_v2.Document(content=caption.text, type_=language_v2.Document.Type.PLAIN_TEXT)
        response = self._client.moderate_text(document=document)

        # Process the moderation response
        is_safe = True
        categories = []
        for category in response.moderation_categories:
            # The API returns scores between 0 and 1. A higher score means more likely to be in that category.
            # We can define a threshold for what's considered "unsafe".
            # For simplicity, let's just list categories with a score above 0.5
            if category.score > 0.5:
                is_safe = False
                categories.append({"name": category.name, "score": category.score})

        return {"text": caption.text, "is_safe": is_safe, "categories": categories, "is_final": caption.is_final}

def live_caption_safety(captions: Iterator[SpeechRecognitionResult]) -> Iterator[Dict[str, Any]]:
    safety_checker = SafetyChecker()
    for caption in captions:
        yield safety_checker.check_safety(caption)

from google.cloud import aiplatform
import vertexai
from vertexai.language_models import TextGenerationModel
from speech_models import SpeechRecognitionResult
from typing import Iterator, Dict, Any

class MeetingSummarizer:
    def __init__(self, project_id: str, location: str = "us-central1"):
        vertexai.init(project=project_id, location=location)
        self._model = TextGenerationModel.from_pretrained("text-bison")

    def summarize_chunk(self, transcript_chunk: str) -> str:
        if not transcript_chunk:
            return ""

        # Vertex AI Generative AI for summarization
        # Using text-bison model, which is good for text generation tasks like summarization.
        prompt = f"Summarize the following meeting transcript chunk: {transcript_chunk}"
        response = self._model.predict(prompt=prompt, temperature=0.2, max_output_tokens=250)
        return response.text

def meeting_summary(transcript_chunks: Iterator[SpeechRecognitionResult], project_id: str) -> Iterator[Dict[str, Any]]:
    summarizer = MeetingSummarizer(project_id)
    combined_transcript = []
    for chunk in transcript_chunks:
        combined_transcript.append(chunk.text)
        if chunk.is_final: # Summarize when a final chunk is received
            full_transcript_segment = " ".join(combined_transcript)
            summary = summarizer.summarize_chunk(full_transcript_segment)
            yield {"summary": summary, "is_final_segment": True}
            combined_transcript = [] # Reset for the next segment
        else:
            yield {"current_transcript_segment": chunk.text, "is_final_segment": False}
